{"function": "() => {
  const headings = Array.from(document.querySelectorAll('h2'));
  const contextHeading = headings.find(h => h.innerText.includes('Context'));
  if (contextHeading) {
    let parent = contextHeading.parentElement;
    let text = '';
    // find next sibling paragraphs
    let sibling = parent.nextElementSibling;
    while (sibling && sibling.tagName !== 'H2') {
      text += sibling.innerText + '\n';
      sibling = sibling.nextElementSibling;
    }
    return { heading: contextHeading.innerText, text };
  }
  return null;
}"}

